        _RESIDUAL_RMS = residualRms ?? RESIDUAL_RMS,
        _TRACE_ID = traceId ?? TRACE_ID,
        _ATTESTATION = ATTESTATION;

  /// Finish building, and store into the [fbBuilder].
  @override
  int finish(fb.Builder fbBuilder) {
    final int? RUN_IDOffset = _RUN_ID == null ? null
        : fbBuilder.writeString(_RUN_ID!);
    final int? STARTED_ATOffset = _STARTED_AT == null ? null
        : fbBuilder.writeString(_STARTED_AT!);
    final int? COMPLETED_ATOffset = _COMPLETED_AT == null ? null
        : fbBuilder.writeString(_COMPLETED_AT!);
    final int? CONFIGURATIONOffset = _CONFIGURATION?.getOrCreateOffset(fbBuilder);
    final int? ITERATIONSOffset = _ITERATIONS == null ? null
        : fbBuilder.writeList(_ITERATIONS!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    final int? EDITED_OBSERVATIONSOffset = _EDITED_OBSERVATIONS == null ? null
        : fbBuilder.writeList(_EDITED_OBSERVATIONS!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    final int? ESTIMATED_PARAMETERSOffset = _ESTIMATED_PARAMETERS == null ? null
        : fbBuilder.writeList(_ESTIMATED_PARAMETERS!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    final int? ESTIMATED_EPOCH_STATEOffset = _ESTIMATED_EPOCH_STATE?.getOrCreateOffset(fbBuilder);
    final int? STATE_COVARIANCEOffset = _STATE_COVARIANCE == null ? null
        : fbBuilder.writeListFloat64(_STATE_COVARIANCE!);
    final int? OCM_CONTENT_IDOffset = _OCM_CONTENT_ID == null ? null
        : fbBuilder.writeString(_OCM_CONTENT_ID!);
    final int? FILTER_HISTORYOffset = _FILTER_HISTORY == null ? null
        : fbBuilder.writeList(_FILTER_HISTORY!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    final int? TRACE_IDOffset = _TRACE_ID == null ? null
        : fbBuilder.writeString(_TRACE_ID!);
    final int? ATTESTATIONOffset = _ATTESTATION?.getOrCreateOffset(fbBuilder);
    fbBuilder.startTable(16);
    fbBuilder.addOffset(0, RUN_IDOffset);
    fbBuilder.addOffset(1, STARTED_ATOffset);
    fbBuilder.addOffset(2, COMPLETED_ATOffset);
    fbBuilder.addOffset(3, CONFIGURATIONOffset);
    fbBuilder.addUint8(4, _CONVERGENCE_REASON?.value);
    fbBuilder.addOffset(5, ITERATIONSOffset);
    fbBuilder.addOffset(6, EDITED_OBSERVATIONSOffset);
    fbBuilder.addOffset(7, ESTIMATED_PARAMETERSOffset);
    fbBuilder.addOffset(8, ESTIMATED_EPOCH_STATEOffset);
    fbBuilder.addUint32(9, _COVARIANCE_DIMENSION);
    fbBuilder.addOffset(10, STATE_COVARIANCEOffset);
    fbBuilder.addOffset(11, OCM_CONTENT_IDOffset);
    fbBuilder.addOffset(12, FILTER_HISTORYOffset);
    fbBuilder.addFloat64(13, _RESIDUAL_RMS);
    fbBuilder.addOffset(14, TRACE_IDOffset);
    fbBuilder.addOffset(15, ATTESTATIONOffset);
    return fbBuilder.endTable();
  }

  /// Convenience method to serialize to byte list.
  @override
  Uint8List toBytes([String? fileIdentifier]) {
    final fbBuilder = fb.Builder(deduplicateTables: false);
    fbBuilder.finish(finish(fbBuilder), fileIdentifier);
    return fbBuilder.buffer;
  }
}
